import { fileURLToPath } from "node:url";

import { NodeRuntime, NodeServices } from "@effect/platform-node";
import { Console, Data, Effect, FileSystem, Path } from "effect";
import * as esbuild from "esbuild";

/** Raised when the runtime bundle cannot be produced, or is stale under `--check`. */
class RuntimeBundleError extends Data.TaggedError("RuntimeBundleError") {}

const program = Effect.gen(function* () {
  const fileSystem = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;

  const packageRoot = fileURLToPath(new URL("..", import.meta.url));
  const outputPath = path.join(packageRoot, "src/templates/runtime-bundle.generated.ts");

  const result = yield* Effect.tryPromise(() =>
    esbuild.build({
      absWorkingDir: packageRoot,
      alias: {
        // Avoid environment-specific package build artifacts when generating the checked-in bundle.
        "@voidhash/paywalls": path.join(
          packageRoot,
          "../../libraries/paywalls/src/runtime/config.ts",
        ),
      },
      entryPoints: ["src/runtime/hydrate.tsx"],
      bundle: true,
      define: {
        "process.env.NODE_ENV": '"production"',
      },
      format: "iife",
      jsx: "automatic",
      jsxImportSource: "preact",
      metafile: false,
      minify: true,
      sourcemap: false,
      target: "es2020",
      treeShaking: true,
      write: false,
    }),
  );

  const bundle = result.outputFiles[0]?.text;
  if (bundle === undefined) {
    yield* Console.error("esbuild did not emit the paywall hydration runtime");
    return yield* new RuntimeBundleError();
  }

  const source = `/** Generated by scripts/generate-runtime-bundle.mjs. */\nexport const PAYWALL_RUNTIME_BUNDLE = ${JSON.stringify(bundle)};\n`;

  if (process.argv.includes("--check")) {
    const current = yield* fileSystem
      .readFileString(outputPath)
      .pipe(Effect.orElseSucceed(() => ""));
    if (current !== source) {
      yield* Console.error("The generated paywall runtime is stale; run pnpm runtime:generate");
      return yield* new RuntimeBundleError();
    }
    return;
  }

  yield* fileSystem.writeFileString(outputPath, source);
});

NodeRuntime.runMain(program.pipe(Effect.provide(NodeServices.layer)));
